def _check_type(self):
        """Check that the device group type is correct.

        :raises: DeviceGroupOperationNotSupported, DeviceGroupNotSupported
        """
        if self.device_group_type == "dynamic":
            if not self.device_group_dynamic_discovery:
                raise DeviceGroupOperationNotSupported(
                    "Dynamic discovery must be enabled for dynamic device groups."
                )
        elif self.device_group_type == "static":
            if self.device_group_dynamic_discovery:
                raise DeviceGroupOperationNotSupported(
                    "Dynamic discovery must be disabled for static device groups."
                )
        else:
            raise DeviceGroupNotSupported(
                "Device group type must be either static or dynamic."
            )

